import type { CategoryId } from './categories';

/** easy = 3–6 years, medium = 7–12 years (D7). */
export type ArtworkLevel = 'easy' | 'medium';

export type SourceType = 'original' | 'purchased' | 'cc0' | 'cc-by' | 'ai-placeholder';

/** One entry of src/data/artworks.json, generated by scripts/build-artworks.mjs (F01). */
export type Artwork = {
  id: string;
  title: { vi: string; en: string };
  category: CategoryId;
  level: ArtworkLevel;
  /** Only 'kids' in v1; 'adult' is prepared for later (D2). */
  audience: 'kids' | 'adult';
  /** Regions counted in the progress %, background not included. Ids 1..regionCount(+1 with background). */
  regionCount: number;
  /** Small regions: colourable, never filled by a neighbour, NOT counted in %. Ids follow the counted ones. */
  optionalRegionCount: number;
  /** Region id of the background (not counted in % done, Q7), or null. */
  backgroundRegion: number | null;
  /** line.png side in px; regions.png side (region id = R + 256·G). */
  size: { line: number; regions: number };
  source: { type: SourceType; ref: string };
  /** 1-based, order of sources.csv. */
  order: number;
};
